import{f as r,o as l,c as a,ah as o}from"./chunks/framework.5bt9HFMa.js";const u=JSON.parse('{"title":"02-进程","description":"本章节讲解的内容是进程的描述、状态转换、控制原语、通信、同步与互斥、死锁问题等的基本概念。","frontmatter":{"title":"02-进程","date":"2025-12-11T00:00:00.000Z","tags":["操作系统","计算机基础"],"description":"本章节讲解的内容是进程的描述、状态转换、控制原语、通信、同步与互斥、死锁问题等的基本概念。","author":"沃以","outline":2,"publish":true,"next":{"text":"02-1 进程的互斥与同步","link":"/series/操作系统/02-1 进程的互斥与同步"},"prev":{"text":"01- 概述","link":"/series/操作系统/01-概述"}},"headers":[],"relativePath":"series/操作系统/02-进程.md","filePath":"series/操作系统/02-进程.md","lastUpdated":1777791679000}'),i={name:"series/操作系统/02-进程.md"};function e(n,t,s,g,h,d){return l(),a("div",null,t[0]||(t[0]=[o(`<h1 id="进程" tabindex="-1">进程 <a class="header-anchor" href="#进程" aria-label="Permalink to &quot;进程&quot;">​</a></h1><h2 id="_1-进程的概念和描述" tabindex="-1">1. 进程的概念和描述 <a class="header-anchor" href="#_1-进程的概念和描述" aria-label="Permalink to &quot;1. 进程的概念和描述&quot;">​</a></h2><h3 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h3><p>进程是程序的一次执行过程，是系统进行资源分配和调度的一个独立单位。</p><h3 id="进程与程序的区别" tabindex="-1">进程与程序的区别 <a class="header-anchor" href="#进程与程序的区别" aria-label="Permalink to &quot;进程与程序的区别&quot;">​</a></h3><ul><li><strong>程序</strong>：具有<strong>顺序性</strong>、<strong>封闭性</strong>、<strong>可再现性</strong>。</li><li><strong>进程</strong>：具有<strong>独立性</strong>（独立地址空间）、<strong>随机性</strong>，并可参与<strong>资源共享</strong>。</li><li><strong>动态性</strong>：进程是动态的，程序是静态的。</li><li><strong>并发性</strong>：进程可以并发执行，程序不能。</li></ul><h3 id="进程的组织" tabindex="-1">进程的组织 <a class="header-anchor" href="#进程的组织" aria-label="Permalink to &quot;进程的组织&quot;">​</a></h3><p>进程主要由<strong>程序集合</strong>、<strong>数据集合</strong>和<strong>进程控制块 (PCB)</strong> 三部分组成。</p><pre class="mermaid mermaid-27">graph LR
    Process[进程] --&gt; Program[程序集合]
    Process --&gt; Data[数据集合]
    Process --&gt; PCB[进程控制块 PCB]
    PCB --&gt; Desc[描述信息]
    PCB --&gt; Control[控制信息]
    PCB --&gt; Resource[资源信息]
    PCB --&gt; Context[现场保护]

    classDef default fill:#f9f,stroke:#333,stroke-width:2px;
    classDef pcb fill:#ccf,stroke:#333,stroke-width:2px;
    class PCB,Desc,Control,Resource,Context pcb;</pre><h3 id="进程控制块-pcb-process-control-block" tabindex="-1">进程控制块 PCB (Process Control Block) <a class="header-anchor" href="#进程控制块-pcb-process-control-block" aria-label="Permalink to &quot;进程控制块 PCB (Process Control Block)&quot;">​</a></h3><p>PCB 是进程存在的唯一标志。主要包含：</p><ol><li><strong>描述信息</strong>：进程号 (PID)、用户标识符 (UID) 等。</li><li><strong>控制信息</strong>：进程状态、优先级、程序入口地址等。</li><li><strong>资源信息</strong>：内存、文件、设备等资源清单。</li><li><strong>现场保护</strong>：CPU 现场信息（各种寄存器值）、上下文结构。</li></ol><h2 id="_2-进程状态及转换" tabindex="-1">2. 进程状态及转换 <a class="header-anchor" href="#_2-进程状态及转换" aria-label="Permalink to &quot;2. 进程状态及转换&quot;">​</a></h2><h3 id="三种基本状态" tabindex="-1">三种基本状态 <a class="header-anchor" href="#三种基本状态" aria-label="Permalink to &quot;三种基本状态&quot;">​</a></h3><ol><li><strong>运行态 (Running)</strong>：进程正在处理机上运行。</li><li><strong>就绪态 (Ready)</strong>：进程已获得除处理机以外的一切所需资源，一旦得到处理机即可运行。</li><li><strong>阻塞态 (Blocked/Waiting)</strong>：进程正在等待某一事件而暂停运行（如等待I/O完成）。</li></ol><h3 id="状态转换" tabindex="-1">状态转换 <a class="header-anchor" href="#状态转换" aria-label="Permalink to &quot;状态转换&quot;">​</a></h3><pre class="mermaid mermaid-28">stateDiagram-v2
    direction LR
    [*] --&gt; 就绪态: 创建
    就绪态 --&gt; 运行态: 调度
    运行态 --&gt; 就绪态: 时间片完/抢占
    运行态 --&gt; 阻塞态: 等待事件/I/O
    阻塞态 --&gt; 就绪态: 事件完成
    运行态 --&gt; [*]: 终止</pre><ul><li><strong>就绪 -&gt; 运行</strong>：调度程序选择一个新的进程运行。</li><li><strong>运行 -&gt; 就绪</strong>：时间片用完，或被更高优先级的进程抢占。</li><li><strong>运行 -&gt; 阻塞</strong>：进程请求I/O，或申请资源失败，或等待某个事件。</li><li><strong>阻塞 -&gt; 就绪</strong>：I/O完成，或申请的资源得到满足，或等待的事件发生。</li></ul><h3 id="注意-不能进行的转换" tabindex="-1">注意：不能进行的转换 <a class="header-anchor" href="#注意-不能进行的转换" aria-label="Permalink to &quot;注意：不能进行的转换&quot;">​</a></h3><ul><li><p><strong>阻塞 -&gt; 运行</strong>：阻塞进程必须先进入就绪队列，等待调度。</p></li><li><p><strong>就绪 -&gt; 阻塞</strong>：进程只有在运行时才能发出I/O请求或等待事件，因此不能直接从就绪变为阻塞。</p></li></ul><h2 id="_3-进程控制-四种原语" tabindex="-1">3. 进程控制（四种原语） <a class="header-anchor" href="#_3-进程控制-四种原语" aria-label="Permalink to &quot;3. 进程控制（四种原语）&quot;">​</a></h2><p>进程控制通过<strong>原语</strong>实现，原语的主要特点是<strong>原子性</strong>（执行期间不允许中断）。</p><ol><li><strong>创建原语 (Create)</strong>： <ul><li>申请空白PCB。</li><li>为新进程分配资源。</li><li>初始化PCB。</li><li>将新进程插入就绪队列。</li></ul></li><li><strong>终止原语 (Destroy)</strong>： <ul><li>从PCB集合中找到终止进程的PCB。</li><li>若进程正在运行，立即剥夺CPU。</li><li>回收进程拥有的所有资源。</li><li>撤销PCB。</li></ul></li><li><strong>阻塞原语 (Block)</strong>： <ul><li>找到要阻塞进程的PCB。</li><li>保护现场，将状态改为阻塞态。</li><li>将PCB插入相应的等待队列。</li></ul></li><li><strong>唤醒原语 (Wakeup)</strong>： <ul><li>在等待队列中找到进程PCB。</li><li>将其从等待队列移出，状态改为就绪态。</li><li>插入就绪队列。</li></ul></li></ol><h2 id="_4-进程的通信" tabindex="-1">4. 进程的通信 <a class="header-anchor" href="#_4-进程的通信" aria-label="Permalink to &quot;4. 进程的通信&quot;">​</a></h2><ol><li><strong>共享内存 (Shared Memory)</strong>： <ul><li>在内存中开辟一个共享存储区，各进程通过对该存储区的读写来实现通信。</li><li>速度最快，需要同步机制配合。</li></ul></li><li><strong>消息传递 (Message Passing)</strong>： <ul><li><strong>直接通信</strong>：发送进程直接把消息发送给接收进程。</li><li><strong>间接通信 (信箱)</strong>：发送进程把消息发送到中间实体（信箱），接收进程从信箱中取得消息。</li></ul></li><li><strong>管道 (Pipe)</strong>： <ul><li>利用一种特殊的 pipe 文件连接两个进程。</li><li>数据单向流动（半双工）。</li><li><strong>匿名管道</strong>通常用于父子进程通信；<strong>命名管道 (FIFO)</strong> 可用于无关进程。</li></ul></li></ol><h2 id="_5-进程同步与互斥" tabindex="-1">5. 进程同步与互斥 <a class="header-anchor" href="#_5-进程同步与互斥" aria-label="Permalink to &quot;5. 进程同步与互斥&quot;">​</a></h2><h3 id="两种制约关系" tabindex="-1">两种制约关系 <a class="header-anchor" href="#两种制约关系" aria-label="Permalink to &quot;两种制约关系&quot;">​</a></h3><ol><li><strong>同步（直接制约关系）</strong>： <ul><li><strong>定义</strong>：为完成某种任务而建立的两个或多个进程，因为需要在某些位置上协调工作次序而产生的制约关系。</li><li><strong>例子</strong>：生产-消费问题（先生产，后消费）。</li></ul></li><li><strong>互斥（间接制约关系）</strong>： <ul><li><strong>定义</strong>：当一个进程进入临界区使用临界资源时，另一个进程必须等待。</li><li><strong>例子</strong>：打印机资源共享。</li></ul></li></ol><h3 id="互斥的执行过程" tabindex="-1">互斥的执行过程 <a class="header-anchor" href="#互斥的执行过程" aria-label="Permalink to &quot;互斥的执行过程&quot;">​</a></h3><pre class="mermaid mermaid-29">sequenceDiagram
    participant P1 as 进程A
    participant Res as 临界资源
    participant P2 as 进程B
    P1-&gt;&gt;Res: P操作(加锁)
    Note over P1,Res: 访问临界区
    P2-&gt;&gt;Res: P操作(尝试加锁)
    Note over P2: 阻塞等待
    P1-&gt;&gt;Res: V操作(解锁)
    Note over P2: 被唤醒
    P2-&gt;&gt;Res: 获得资源</pre><h3 id="信号量机制-pv操作" tabindex="-1">信号量机制 (PV操作) <a class="header-anchor" href="#信号量机制-pv操作" aria-label="Permalink to &quot;信号量机制 (PV操作)&quot;">​</a></h3><p>用于解决同步与互斥问题的有效工具。</p><ul><li><strong>P操作 (wait)</strong>：申请资源。<code>S = S - 1</code>，若 <code>S &lt; 0</code>，进程进入阻塞队列。</li><li><strong>V操作 (signal)</strong>：释放资源。<code>S = S + 1</code>，若 <code>S &lt;= 0</code>，唤醒一个阻塞进程。</li><li><strong>注意</strong>：互斥信号量初值通常为 1；同步信号量初值由资源数量决定。</li></ul><h2 id="_6-死锁问题" tabindex="-1">6. 死锁问题 <a class="header-anchor" href="#_6-死锁问题" aria-label="Permalink to &quot;6. 死锁问题&quot;">​</a></h2><h3 id="概念-1" tabindex="-1">概念 <a class="header-anchor" href="#概念-1" aria-label="Permalink to &quot;概念&quot;">​</a></h3><p>多个进程因竞争资源而造成的一种僵局（互相等待），若无外力作用，这些进程都将无法向前推进。</p><h3 id="死锁产生的四个必要条件" tabindex="-1">死锁产生的四个必要条件 <a class="header-anchor" href="#死锁产生的四个必要条件" aria-label="Permalink to &quot;死锁产生的四个必要条件&quot;">​</a></h3><ol><li><strong>互斥条件</strong>：资源是独占的。</li><li><strong>不剥夺条件</strong>：进程获得的资源在未使用完之前，不能被其他进程强行夺走。</li><li><strong>请求和保持条件</strong>：进程已经保持了至少一个资源，但又提出了新的资源请求。</li><li><strong>循环等待条件</strong>：存在一种进程资源的循环等待链。</li></ol><h3 id="死锁预防" tabindex="-1">死锁预防 <a class="header-anchor" href="#死锁预防" aria-label="Permalink to &quot;死锁预防&quot;">​</a></h3><p>破坏四个必要条件中的一个或多个：</p><ul><li>破坏互斥条件（一般不现实）。</li><li>破坏不剥夺条件（实现复杂，代价大）。</li><li>破坏请求和保持条件（一次性申请所有资源）。</li><li>破坏循环等待条件（资源有序分配法）。</li></ul><h3 id="死锁避免-银行家算法" tabindex="-1">死锁避免 - 银行家算法 <a class="header-anchor" href="#死锁避免-银行家算法" aria-label="Permalink to &quot;死锁避免 - 银行家算法&quot;">​</a></h3><ul><li><strong>核心思想</strong>：在资源分配前，先计算此次分配是否会导致系统进入<strong>不安全状态</strong>。如果会，则不分配；否则分配。</li><li><strong>安全序列</strong>：指如果系统按照这种序列分配资源，则每个进程都能顺利完成。只要能找出一个安全序列，系统就是安全的。</li></ul><h2 id="_7-线程" tabindex="-1">7. 线程 <a class="header-anchor" href="#_7-线程" aria-label="Permalink to &quot;7. 线程&quot;">​</a></h2><h3 id="概念-2" tabindex="-1">概念 <a class="header-anchor" href="#概念-2" aria-label="Permalink to &quot;概念&quot;">​</a></h3><p>线程是程序执行流的最小单元。</p><h3 id="进程与线程的关系" tabindex="-1">进程与线程的关系 <a class="header-anchor" href="#进程与线程的关系" aria-label="Permalink to &quot;进程与线程的关系&quot;">​</a></h3><pre class="mermaid mermaid-30">graph TD
    subgraph Process[进程]
        T1((线程1))
        T2((线程2))
        T3((线程3))
        Res[资源: 内存/文件]
        T1 --- Res
        T2 --- Res
        T3 --- Res
    end
    style Process fill:#f9f,stroke:#333,stroke-width:2px
    style Res fill:#ccf</pre><h3 id="引入线程后的变化" tabindex="-1">引入线程后的变化 <a class="header-anchor" href="#引入线程后的变化" aria-label="Permalink to &quot;引入线程后的变化&quot;">​</a></h3><ol><li><strong>资源分配</strong>：<strong>进程</strong>依然是资源分配的基本单位。</li><li><strong>调度</strong>：<strong>线程</strong>成为CPU调度和分派的基本单位。</li><li><strong>并发性</strong>：不仅进程之间可以并发，同一个进程中的多个线程也可以并发执行。</li><li><strong>系统开销</strong>：线程创建、切换的开销远小于进程。</li></ol>`,50)]))}const P=r(i,[["render",e]]);export{u as __pageData,P as default};
